      "id": "MED-PARTNER-T1-WARNING-001",
      "topic": "孕初期：認識流產警訊",
      "category": "partner_support",
      "partner_type": "warning_sign_support",
      "audience": "partner",
      "pregnancy_stage": "trimester_1",
      "recommended_window": "1-12 weeks",
